package kr.or.arte.seal.rights.persistence;
import kr.or.arte.seal.rights.application.*;import kr.or.arte.seal.rights.domain.*;import org.springframework.stereotype.Repository;import java.time.*;import java.util.*;
@Repository public class MyBatisRightsRequestRepository implements RightsRequestRepository {private final RightsRequestMapper mapper;public MyBatisRightsRequestRepository(RightsRequestMapper m){mapper=m;}public void insert(RightsRequestRecord r){mapper.insert(r);}public List<RightsRequestSummary> search(UUID a,RightsRequestStatus s){return mapper.search(a,s);}public Optional<RightsRequestRecord> findScoped(UUID a,UUID id){return mapper.findScoped(a,id);}public Optional<RightsRequestRecord> findScopedForUpdate(UUID a,UUID id){return mapper.findScopedForUpdate(a,id);}public void transition(UUID id,RightsRequestStatus f,RightsRequestStatus t,UUID a,String c,byte[] v,String k,String d,byte[] result,Instant n,long version){if(mapper.transition(id,f,t,a,c,v,k,d,result,n,version)!=1)throw new IllegalStateException("권리요청이 다른 사용자에 의해 변경되었습니다.");}public void insertEvent(UUID id,RightsRequestStatus f,RightsRequestStatus t,UUID a,String r,Instant n){mapper.event(UUID.randomUUID(),id,f,t,a,r,n);}public void insertWithdrawal(UUID rights,UUID response,UUID actor,Instant now){mapper.withdrawal(UUID.randomUUID(),rights,response,actor,now);}public Optional<UUID> responseId(UUID request){return mapper.responseId(request);}public void linkRetentionJob(UUID rights,UUID job,long version){if(mapper.linkRetentionJob(rights,job,version)!=1)throw new IllegalStateException("삭제 작업 연결에 실패했습니다.");}}
